const doomEyeSheet=new Image();doomEyeSheet.assetSrc='assets/doom-eye-v1.png';
function beginDoomEye(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'doomOccludedBeam',bespoke:true,windup:1.8,origin:{x:e.x,y:e.y},fired:false,angle:Math.atan2(p.y-e.y,p.x-e.x),length:500};e.attack.terrainLength=doomEyeTerrain(e.attack);e.facing=Math.cos(e.attack.angle)-Math.sin(e.attack.angle)<0?-1:1;}
function doomEyeLane(a,point){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,along=dx*Math.cos(a.angle)+dy*Math.sin(a.angle),side=-dx*Math.sin(a.angle)+dy*Math.cos(a.angle);return along>=0&&along<=a.length+1e-8&&Math.abs(side)<=24+1e-8&&lineClear(a.origin,point);}
function doomEyeTerrain(a){let length=0;for(let d=5;d<=500;d+=5){let q={x:a.origin.x+Math.cos(a.angle)*d,y:a.origin.y+Math.sin(a.angle)*d};if(!passable(q.x,q.y,0)||!lineClear(a.origin,q))break;length=d;}return length;}
function doomEyeReach(e,a,refreshTerrain=true){let length=refreshTerrain?doomEyeTerrain(a):a.terrainLength,blocker=null,ux=Math.cos(a.angle),uy=Math.sin(a.angle);for(let other of enemies){if(other===e||!(other.hp>0))continue;let dx=other.x-a.origin.x,dy=other.y-a.origin.y,along=dx*ux+dy*uy,side=-dx*uy+dy*ux;if(along<0||Math.abs(side)>48)continue;let near=Math.max(0,along-Math.sqrt(Math.max(0,48*48-side*side)));if(near<length&&lineClear(a.origin,other)){length=near;blocker=other;}}return {length,blocker};}
const doomEyeAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r11e6')return doomEyeAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='doomOccludedBeam'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=480&&clear){beginDoomEye(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,65*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed+=dt;
 if(!a.fired&&e.elapsed+1e-8>=a.windup){a.fired=true;e.struck=true;let reach=doomEyeReach(e,a);a.length=reach.length;a.blocked=!!reach.blocker;if(doomEyeLane(a,p))hurt(100);playSound('impact',e.x,e.y);}
 if(e.elapsed>=a.windup+1){e.attack=null;e.state='idle';e.t=2.8;}
};
const doomEyeDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r11e6'||!doomEyeSheet.complete||!doomEyeSheet.naturalWidth||!doomEyeSheet.naturalHeight)return doomEyeDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='doomOccludedBeam')f={row:2,col:e.elapsed<a.windup?(e.elapsed>.9?1:0):e.elapsed<a.windup+.25?2:3};let q=project(e.x,e.y),sw=doomEyeSheet.naturalWidth/4,sh=doomEyeSheet.naturalHeight/3,w=235,h=w*sh/sw,anchor=[[.81,.81,.81,.81],[.81,.81,.81,.81],[.81,.81,.81,.81]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y-18-Math.sin((e.anim||0)*2)*3);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,doomEyeSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(doomEyeSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const doomEyeSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r11e6'?175:doomEyeSizeBase(e);
const doomEyeGroundBase=drawGroundEffects;drawGroundEffects=()=>{doomEyeGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r11e6'):enemies)){let a=e.attack;if(e.species!=='r11e6'||e.hp<=0||a?.pattern!=='doomOccludedBeam'||e.elapsed>a.windup+.3||!visibleAt(e.x,e.y))continue;let reach=a.fired?{length:a.length,blocker:null}:doomEyeReach(e,a,false);if(reach.blocker)groundRing(reach.blocker.x,reach.blocker.y,48,'#f0ce8e',3);let ux=Math.cos(a.angle),uy=Math.sin(a.angle),end={x:a.origin.x+ux*reach.length,y:a.origin.y+uy*reach.length};ctx.save();ctx.beginPath();[[a.origin.x-uy*24,a.origin.y+ux*24],[end.x-uy*24,end.y+ux*24],[end.x+uy*24,end.y-ux*24],[a.origin.x+uy*24,a.origin.y-ux*24]].forEach(([x,y],i)=>{let q=project(x,y);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fillStyle=a.fired?'rgba(224,169,255,.4)':'rgba(180,106,220,.15)';ctx.strokeStyle='#dfacfa';ctx.lineWidth=2;ctx.fill();ctx.stroke();ctx.restore();}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r11e6',animateEnemy,drawRegionEnemy);
